/** 
 * Sets the attribute in the element under the name. <p> Automatically appends  {@link #PREFIX} to the beginning of the namebefore assigning the attribute to the element.
 * @param element element to set the attribute in
 * @param name name of the attribute (without prefix)
 * @param attribute attribute to save
 */
public static void setAttribute(Element element,String name,String attribute){
  try {
    element.setAttribute(PREFIX + name, attribute);
  } catch (org.w3c.dom.DOMException e) {
    // Handle the exception, e.g., log the error or throw a custom runtime exception
    throw new RuntimeException("Failed to set attribute due to invalid input or read-only element", e);
  }
}
